def comps(g):
 R,C=len(g),len(g[0]); seen=set(); out=[]
 for i in range(R):
  for j in range(C):
   if g[i][j]==0 or (i,j) in seen: continue
   col=g[i][j]; st=[(i,j)]; seen.add((i,j)); pts=[]
   while st:
    p=st.pop();pts.append(p)
    for di,dj in ((0,1),(1,0),(-1,0),(0,-1)):
     q=(p[0]+di,p[1]+dj)
     if 0<=q[0]<R and 0<=q[1]<C and g[q[0]][q[1]]==col and q not in seen:seen.add(q);st.append(q)
   out.append((col,pts))
 return sorted(out,key=lambda x:-len(x[1]))
