def two_color_windows(g,t):
 hits=[]
 for i in range(5):
  for j in range(5):
   vals=[[g[i+r][j+c] for c in range(3)] for r in range(3)]
   uniq=set(x for row in vals for x in row)
   if len(uniq)==2:
    for col in uniq:
     mask=[[int(vals[r][c]==col) for c in range(3)] for r in range(3)]
     if mask==t: hits.append((i,j,col,uniq,vals))
 return hits
