def closest(g,t):
 outlist=[]
 for i in range(5):
  for j in range(5):
   vals=[[g[i+r][j+c] for c in range(3)] for r in range(3)]
   for col in set(x for row in vals for x in row):
    mask=[[int(vals[r][c]==col) for c in range(3)] for r in range(3)]
    d=sum(mask[r][c]!=t[r][c] for r in range(3) for c in range(3))
    outlist.append((d,i,j,col,mask,vals))
 return sorted(outlist)[:5]
